package com.medicore.fulfillment.entity; import jakarta.persistence.*; @Entity @Table(name="fulfillments") public class Fulfillment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long orderId; @Column(nullable=false) private String status="PENDING"; protected Fulfillment(){} public Fulfillment(Long orderId){this.orderId=orderId;} public Long getId(){return id;} public Long getOrderId(){return orderId;} public String getStatus(){return status;} public void setStatus(String s){status=s;}}
